def convert_type(ty: t.Any | None=None, default: t.Any | None=None) -> ParamType[t.Any]:
    guessed = _guess_type(ty, default)
    is_guessed = guessed is not ty
    if isinstance(guessed, tuple):
        return Tuple(guessed)
    if isinstance(guessed, ParamType):
        return guessed
    if guessed is str or guessed is None:
        return STRING
    if guessed is int:
        return INT
    if guessed is float:
        return FLOAT
    if guessed is bool:
        return BOOL
    if is_guessed:
        return STRING
    if __debug__:
        try:
            if issubclass(guessed, ParamType):
                raise AssertionError(f'Attempted to use an uninstantiated parameter type ({guessed}).')
        except TypeError:
            pass
    return FuncParamType(guessed)
