def test_slots_with_multiple_cached_property_subclasses_works():

    @attr.s(slots=True)
    class A:
        x = attr.ib(kw_only=True)

        @functools.cached_property
        def f(self):
            return self.x

    @attr.s(slots=False)
    class B:

        @functools.cached_property
        def g(self):
            return self.x * 2

        def __getattr__(self, item):
            if hasattr(super(), '__getattr__'):
                return super().__getattr__(item)
            return item

    @attr.s(slots=True)
    class AB(A, B):
        pass
    ab = AB(x=1)
    assert ab.f == 1
    assert ab.g == 2
    assert ab.h == 'h'
```

