def test_multipart_encode_non_seekable_filelike() -> None:
    """
    Test that special readable but non-seekable filelike objects are supported.
    In this case uploads with use 'Transfer-Encoding: chunked', instead of
    a 'Content-Length' header.
    """

    class IteratorIO(io.IOBase):

        def __init__(self, iterator: typing.Iterator[bytes]) -> None:
            self._iterator = iterator

        def read(self, *args: typing.Any) -> bytes:
            return b''.join(self._iterator)

    def data() -> typing.Iterator[bytes]:
        yield b'Hello'
        yield b'World'
    url = 'https://www.example.com/'
    headers = {'Content-Type': 'multipart/form-data; boundary=BOUNDARY'}
    fileobj: typing.Any = IteratorIO(data())
    files = {'file': fileobj}
    request = httpx.Request('POST', url, headers=headers, files=files)
    request.read()
    assert request.headers == {'Host': 'www.example.com', 'Content-Type': 'multipart/form-data; boundary=BOUNDARY', 'Transfer-Encoding': 'chunked'}
    assert request.content == b'--BOUNDARY\r\nContent-Disposition: form-data; name="file"; filename="upload"\r\nContent-Type: application/octet-stream\r\n\r\nHelloWorld\r\n--BOUNDARY--\r\n'
