def extract_from_ast(ast: nodes.Template, gettext_functions: t.Sequence[str]=GETTEXT_FUNCTIONS, babel_style: bool=True) -> t.Iterator[tuple[int, str, str | None | tuple[str | None, ...]]]:
    out: str | None | tuple[str | None, ...]
    for node in ast.find_all(nodes.Call):
        if not isinstance(node.node, nodes.Name) or node.node.name not in gettext_functions:
            continue
        strings: list[str | None] = []
        for arg in node.args:
            if isinstance(arg, nodes.Const) and isinstance(arg.value, str):
                strings.append(arg.value)
            else:
                strings.append(None)
        for _ in node.kwargs:
            strings.append(None)
        if node.dyn_args is not None:
            strings.append(None)
        if node.dyn_kwargs is not None:
            strings.append(None)
        if not babel_style:
            out = tuple((x for x in strings if x is not None))
            if not out:
                continue
        elif len(strings) == 1:
            out = strings[0]
        else:
            out = tuple(strings)
        yield (node.lineno, node.node.name, out)
```

