def evolve(*args, **changes):
    try:
        inst, = args
    except ValueError:
        msg = f'evolve() takes 1 positional argument, but {len(args)} were given'
        raise TypeError(msg) from None
    cls = inst.__class__
    attrs = fields(cls)
    for a in attrs:
        if not a.init:
            continue
        attr_name = a.name
        init_name = a.alias
        if init_name not in changes:
            changes[init_name] = getattr(inst, attr_name)
    return cls(**changes)
