    @attr.s(slots=True)
    class A:
        x = attr.ib()

        @property
        def f(self):
            return self.x

    @attr.s(slots=True)
    class B(A):

        @property
        def f(self):
            return super().f ** 2
    assert B(11).f == 121
    assert B(17).f == 289
