def urlize(text: str, trim_url_limit: int | None=None, rel: str | None=None, target: str | None=None, extra_schemes: t.Iterable[str] | None=None) -> str:
    if trim_url_limit is not None:

        def trim_url(x: str) -> str:
            if len(x) > trim_url_limit:
                return f'{x[:trim_url_limit]}...'
            return x
    else:

        def trim_url(x: str) -> str:
            return x
    words = re.split('(\\s+)', str(markupsafe.escape(text)))
    rel_attr = f' rel="{markupsafe.escape(rel)}"' if rel else ''
    target_attr = f' target="{markupsafe.escape(target)}"' if target else ''
    for i, word in enumerate(words):
        head, middle, tail = ('', word, '')
        match = re.match('^([(<]|&lt;)+', middle)
        if match:
            head = match.group()
            middle = middle[match.end():]
        if middle.endswith((')', '>', '.', ',', '\n', '&gt;')):
            match = re.search('([)>.,\\n]|&gt;)+$', middle)
            if match:
                tail = match.group()
                middle = middle[:match.start()]
        for start_char, end_char in (('(', ')'), ('<', '>'), ('&lt;', '&gt;')):
            start_count = middle.count(start_char)
            if start_count <= middle.count(end_char):
                continue
