def markdown_lines(file):
    fence = None
    with open(file, encoding='utf-8') as content:
        for lineno, line in enumerate(content, 1):
            line = line.rstrip('\n')
            match = FENCE_RE.match(line)
            if fence is None:
                if match:
                    fence = match.group(1)
                else:
                    yield (lineno, line)
            elif match and line.strip() == match.group(1) and (match.group(1)[0] == fence[0]) and (len(match.group(1)) >= len(fence)):
                fence = None
