def do_indent(s: str, width: int | str=4, first: bool=False, blank: bool=False) -> str:
    if isinstance(width, str):
        indention = width
    else:
        indention = ' ' * width
    newline = '\n'
    if isinstance(s, Markup):
        indention = Markup(indention)
        newline = Markup(newline)
    s += newline
    if blank:
        rv = (newline + indention).join(s.splitlines())
    else:
        lines = s.splitlines()
        rv = lines.pop(0)
        if lines:
            rv += newline + newline.join((indention + line if line else line for line in lines))
    if first:
        rv = indention + rv
    return rv
```

