def make_logging_undefined(logger: t.Optional['logging.Logger']=None, base: type[Undefined]=Undefined) -> type[Undefined]:
    if logger is None:
        import logging
        logger = logging.getLogger(__name__)
        logger.addHandler(logging.StreamHandler(sys.stderr))

    def _log_message(undef: Undefined) -> None:
        logger.warning('Template variable warning: %s', undef._undefined_message)

    class LoggingUndefined(base):
        __slots__ = ()

        def _fail_with_undefined_error(self, *args: t.Any, **kwargs: t.Any) -> 'te.NoReturn':
            try:
                super()._fail_with_undefined_error(*args, **kwargs)
            except self._undefined_exception as e:
                logger.error('Template variable error: %s', e)
                raise e

        def __str__(self) -> str:
            _log_message(self)
            return super().__str__()

        def __iter__(self) -> t.Iterator[t.Any]:
            _log_message(self)
            return super().__iter__()

        def __bool__(self) -> bool:
            _log_message(self)
            return super().__bool__()
    return LoggingUndefined
```

