def do_batch(value: 't.Iterable[V]', linecount: int, fill_with: 'V | None'=None) -> 't.Iterator[list[V]]':
    tmp: list[V] = []
    for item in value:
        if len(tmp) == linecount:
            yield tmp
            tmp = []
        tmp.append(item)
    if tmp:
        if fill_with is not None and len(tmp) < linecount:
            tmp += [fill_with] * (linecount - len(tmp))
        yield tmp
