def test_slots_super_property_get():

    @attr.s(slots=True)
    class A:
        x = attr.ib()

        @property
        def f(self):
            return self.x

    @attr.s(slots=True)
    class B(A):

        @property
        def f(self):
            return super().f ** 2

    @attr.s(slots=True)
    class C(A):

        @property
        def f(self):
            return super(C, self).f ** 2
    assert B(11).f == 121
    assert B(17).f == 289
    assert C(11).f == 121
    assert C(17).f == 289
```

