def _parse_version(version: str) -> tuple[int, int, int]:
    version_integers: tuple[int, ...]
    try:
        version_integers = tuple(map(int, version.split('.')))
    except ValueError:
        raise ValueError(f'unicode version string {version!r} is badly formatted') from None
    while len(version_integers) < 3:
        version_integers = version_integers + (0,)
    triple = cast('tuple[int, int, int]', version_integers[:3])
    return triple
```

