def test_inherited_slot_reuses_slot_descriptor():

    class HasXSlot:
        __slots__ = ('x',)

    class OverridesX(HasXSlot):

        @property
        def x(self):
            return None

    @attr.s(slots=True)
    class Child(OverridesX):
        x = attr.ib()
    assert Child.x is not OverridesX.x
    assert Child.x is HasXSlot.x
    c = Child(1)
    assert 1 == c.x
    assert set() == set(Child.__slots__)
    ox = OverridesX()
    assert ox.x is None
```

