            return
        msg = message.split(marker)[0].rstrip()
        if not msg:
            click.echo('Aborted! Empty commit message')
            return
    else:
        msg = '\n'.join(message)
    click.echo(f'Files to be committed: {files}')
    click.echo(f'Commit message:\n{msg}')
