def _make_eq_script(attrs: list) -> tuple[str, dict]:
    attrs = [a for a in attrs if a.eq]
    lines = ['def __eq__(self, other):', '    if other.__class__ is not self.__class__:', '        return NotImplemented']
    globs = {}
    if attrs:
        lines.append('    return  (')
        for a in attrs:
            if a.eq_key:
                cmp_name = f'_{a.name}_key'
                globs[cmp_name] = a.eq_key
                lines.append(f'        {cmp_name}(self.{a.name}) == {cmp_name}(other.{a.name})')
            else:
                lines.append(f'        self.{a.name} == other.{a.name}')
            if a is not attrs[-1]:
                lines[-1] = f'{lines[-1]} and'
        lines.append('    )')
    else:
        lines.append('    return True')
    script = '\n'.join(lines)
    return (script, globs)
```

