def find_app_by_string(module: ModuleType, app_name: str) -> Flask:
    from . import Flask
    try:
        expr = ast.parse(app_name.strip(), mode='eval').body
    except SyntaxError:
        raise NoAppException(f'Failed to parse {app_name!r} as an attribute name or function call.') from None
    if isinstance(expr, ast.Name):
        name = expr.id
        args = []
        kwargs = {}
    elif isinstance(expr, ast.Call):
        if not isinstance(expr.func, ast.Name):
            raise NoAppException(f'Function reference must be a simple name: {app_name!r}.')
        name = expr.func.id
        try:
            args = [ast.literal_eval(arg) for arg in expr.args]
            kwargs = {kw.arg: ast.literal_eval(kw.value) for kw in expr.keywords if kw.arg is not None}
        except ValueError:
            raise NoAppException(f'Failed to parse arguments as literal values: {app_name!r}.') from None
    else:
        raise NoAppException(f'Failed to parse {app_name!r} as an attribute name or function call.')
