def test_get_pager_file_flushes_stream_on_exception(monkeypatch):

    class FlushableTextStream(io.StringIO):

        def __init__(self):
            super().__init__()
            self.flush_calls = 0

        def flush(self):
            self.flush_calls += 1
    stream = FlushableTextStream()

